package com.sigtm.backend.service;
import com.sigtm.backend.dto.EstadoPresupuestoCompraResponse; import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.YearMonth;
@Service @RequiredArgsConstructor public class PresupuestoCompraService { private final PresupuestoCompraRepository budgets; private final OrdenCompraRepository orders; private final AuditoriaService audit;
 @Transactional public PresupuestoCompra guardar(PresupuestoCompra data){YearMonth.parse(data.getPeriod());if(data.getAlertPercentage()==null)data.setAlertPercentage(80); PresupuestoCompra saved=budgets.save(data);audit.registrar("UPDATE","PRESUPUESTO_COMPRA",saved.getId(),"Presupuesto "+saved.getPeriod());return saved;}
 @Transactional(readOnly=true) public EstadoPresupuestoCompraResponse estado(String period){PresupuestoCompra b=budgets.findByPeriod(period).orElseThrow(()->new ResourceNotFoundException("Presupuesto no encontrado"));BigDecimal committed=orders.findAll().stream().filter(o->!"ANULADA".equals(o.getStatus())&&YearMonth.from(o.getIssueDate()).toString().equals(period)).map(OrdenCompra::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal pct=committed.multiply(BigDecimal.valueOf(100)).divide(b.getLimitAmount(),2,RoundingMode.HALF_UP);String status=pct.compareTo(BigDecimal.valueOf(100))>=0?"EXCEDIDO":pct.compareTo(BigDecimal.valueOf(b.getAlertPercentage()))>=0?"ALERTA":"DISPONIBLE";return new EstadoPresupuestoCompraResponse(period,b.getLimitAmount(),committed,b.getLimitAmount().subtract(committed),pct,status);}}
